//! decode_photo / decode_oriented on the sample files in tests/sample-images/.
//!
//! Format fixtures are 64x48 gradients (red grows left to right, green top to
//! bottom), regenerated by tests/sample-images/make_format_fixtures.py.

use std::path::PathBuf;

use image::{DynamicImage, GenericImageView};
use image_proc::decode::{decode_oriented, decode_photo};

fn sample(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../tests/sample-images")
        .join(name)
}

/// Asserts a 64x48 upright gradient: right edge redder than left, bottom
/// greener than top. Grayscale fixtures carry the green ramp only.
fn assert_gradient(name: &str, img: &DynamicImage) {
    assert_eq!(img.dimensions(), (64, 48), "{name}: wrong size");
    let rgb = img.to_rgb8();
    let [l, r] = [rgb.get_pixel(2, 24), rgb.get_pixel(61, 24)];
    let [t, b] = [rgb.get_pixel(32, 2), rgb.get_pixel(32, 45)];
    let gray = l[0] == l[1] && l[1] == l[2];
    if !gray {
        assert!(
            r[0] > l[0] + 100,
            "{name}: no left-to-right red ramp ({l:?} → {r:?})"
        );
    }
    assert!(
        b[1] > t[1] + 100,
        "{name}: no top-to-bottom green ramp ({t:?} → {b:?})"
    );
}

fn decode_sample(name: &str) -> DynamicImage {
    let ext = format!(".{}", name.rsplit('.').next().unwrap());
    decode_photo(&sample(name), &ext, 64).unwrap_or_else(|e| panic!("{name}: {e}"))
}

#[test]
fn decode_standard_formats() {
    for name in [
        "001.jpg",
        "tiff_rgb16.tif",
        "tiff_gray16.tif",
        "tiff_lzw.tif",
        "tiff_jpeg.tif",
        "tiff_cmyk.tif",
        "webp_lossless.webp",
    ] {
        let img = decode_sample(name);
        if name != "001.jpg" {
            assert_gradient(name, &img);
        }
    }
}

#[test]
fn decode_multipage_and_animated_files_give_first_image() {
    // The second page / frame is a solid red square: a gradient means the first.
    for name in [
        "tiff_multipage.tif",
        "webp_animated.webp",
        "gif_animated.gif",
    ] {
        assert_gradient(name, &decode_sample(name));
    }
}

#[test]
fn decode_bmp() {
    assert_gradient("bmp_rgb.bmp", &decode_sample("bmp_rgb.bmp"));
}

#[test]
fn decode_jpeg_xl_8_and_16_bit() {
    assert_gradient("jxl_8bit.jxl", &decode_sample("jxl_8bit.jxl"));
    assert_gradient("jxl_16bit.jxl", &decode_sample("jxl_16bit.jxl"));
}

#[test]
fn standard_format_is_detected_from_content() {
    // A JPEG saved with a .png extension still decodes.
    let img = decode_photo(&sample("001.jpg"), ".png", 64).unwrap();
    assert!(img.width() > 0);
}

#[test]
fn orientation_applies_to_standard_formats() {
    let img = decode_oriented(&sample("tiff_lzw.tif"), ".tif", Some(6), 64).unwrap();
    assert_eq!(img.dimensions(), (48, 64));
}

#[test]
fn orientation_is_ignored_for_jpeg_xl() {
    // jxl-oxide already applies the file's own orientation.
    let img = decode_oriented(&sample("jxl_8bit.jxl"), ".jxl", Some(6), 64).unwrap();
    assert_eq!(img.dimensions(), (64, 48));
}

#[cfg(feature = "heic")]
#[test]
fn decode_heic_returns_correct_dimensions() {
    // 64x48 gradient, generated via pillow-heif.
    let img = decode_photo(&sample("003.heic"), ".heic", 64).unwrap();
    assert_eq!(img.dimensions(), (64, 48));
}

#[cfg(feature = "heic")]
#[test]
fn decode_hif_goes_through_libheif() {
    // Canon/Sony write HEIF as .hif: same container as .heic.
    let img = decode_photo(&sample("003.heic"), ".HIF", 64).unwrap();
    assert_eq!(img.dimensions(), (64, 48));
}

#[cfg(feature = "heic")]
#[test]
fn decode_avif_8_and_10_bit() {
    // Needs libheif built with an AV1 decoder (aom or dav1d).
    assert_gradient("avif_8bit.avif", &decode_sample("avif_8bit.avif"));
    assert_gradient("avif_10bit.avif", &decode_sample("avif_10bit.avif"));
}

#[cfg(feature = "heic")]
#[test]
fn orientation_is_ignored_for_heif_family() {
    // libheif already applies the file's rotation and mirror transforms.
    for (name, ext) in [("003.heic", ".heic"), ("avif_8bit.avif", ".avif")] {
        let img = decode_oriented(&sample(name), ext, Some(6), 64).unwrap();
        assert_eq!(img.dimensions(), (64, 48), "{name}");
    }
}

// 004.dng: Sigma fp DNG, 16:9, CC0, from raw.pixls.us
// ("Sigma - fp - 8bit (16:9).DNG", sha256 80ae0b8f…ad0c).

#[cfg(feature = "raw")]
#[test]
fn decode_raw_dng_for_thumbnail() {
    let img = decode_photo(&sample("004.dng"), ".DNG", 256).unwrap();
    let (w, h) = img.dimensions();
    assert!(w >= 256, "long edge {w} smaller than requested");
    assert_eq!((w * 9 + h / 2) / h, 16, "expected 16:9, got {w}x{h}");
}

#[cfg(feature = "raw")]
#[test]
fn decode_raw_develops_when_embedded_jpeg_too_small() {
    // No embedded JPEG is this large, so this forces the develop path.
    let img = decode_photo(&sample("004.dng"), ".dng", u32::MAX).unwrap();
    let (w, h) = img.dimensions();
    assert_eq!((w * 9 + h / 2) / h, 16, "expected 16:9, got {w}x{h}");
    // Developed output is not black: auto exposure ran.
    let mean = img.to_luma8().pixels().map(|p| p[0] as u64).sum::<u64>() / (w * h) as u64;
    assert!(mean > 40, "developed image too dark (mean luma {mean})");
}

#[cfg(feature = "raw")]
#[test]
fn decode_raw_rejects_non_raw_file_without_panicking() {
    let err = decode_photo(&sample("001.jpg"), ".nef", 256).unwrap_err();
    assert!(err.contains("failed to decode RAW"), "{err}");
}

#[cfg(feature = "raw")]
#[test]
fn decode_raw_missing_file_is_an_error() {
    let err = decode_photo(&PathBuf::from("/nonexistent/x.cr2"), ".cr2", 256).unwrap_err();
    assert!(err.contains("failed to decode RAW"), "{err}");
}
